SELECT country, CASE WHEN credit_limit >= 16400 THEN 'high' WHEN credit_limit >= 4400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, SUM(CASE WHEN city = 'Bangkok' THEN age ELSE 0 END) AS bangkok_age FROM customers GROUP BY country, CASE WHEN credit_limit >= 16400 THEN 'high' WHEN credit_limit >= 4400 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN city = 'Bangkok' THEN age ELSE 0 END) > 39;
